import type {Bootstrap} from './types';
let token='';
export async function bootstrap():Promise<Bootstrap>{const response=await fetch('/api/bootstrap');if(!response.ok||!response.headers.get('content-type')?.includes('application/json'))throw new Error('Nested is a Mac app. Download it to read on your computer, or run npm run dev for local development.');const data=await response.json();token=data.token;return data;}
export async function api<T>(path:string,method='GET',body?:unknown):Promise<T>{const response=await fetch(`/api${path}`,{method,headers:{'Content-Type':'application/json','X-Nested-Token':token},body:body===undefined?undefined:JSON.stringify(body)});if(!response.ok){const data=await response.json().catch(()=>({error:'The request could not be completed.'}));throw new Error(data.error);}return response.json();}
export async function downloadBook(id:string,title:string){const response=await fetch(`/api/books/${id}/export`,{headers:{'X-Nested-Token':token}});if(!response.ok)throw new Error('The book could not be exported. Try again.');saveBlob(await response.blob(),`${title.replace(/[^a-z0-9]+/gi,'-')}.zip`);}
export function saveBlob(blob:Blob,name:string){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export async function generate(body:unknown,signal:AbortSignal,onEvent:(event:any)=>void){const response=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json','X-Nested-Token':token},body:JSON.stringify(body),signal});if(!response.ok)throw new Error((await response.json()).error);const reader=response.body!.getReader(),decoder=new TextDecoder();let buffer='',completed=false;while(true){const {done,value}=await reader.read();buffer+=decoder.decode(value,{stream:!done});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines){if(!line.trim())continue;const event=JSON.parse(line);if(event.type==='error')throw new Error(event.error);if(event.type==='complete')completed=true;onEvent(event);}if(done)break;}if(!completed)throw new Error('The connection ended before the explanation was saved. Please try again.');}
